INSERT INTO temporary_questions (essence_fk, text, points, options) VALUES
-- Lernfeld 1 > IT-Arbeitsplätze im Kontext > Leistungsportfolio Ausbildungsbetrieb > IT-Bereich Services
-- Ja/Nein-Fragen (5 Stück)
('00000000-0000-0000-0000-000000000000', 'Müssen IT-Bereich Services im Ausbildungsbetrieb die Bedürfnisse der Auszubildenden berücksichtigen?', 2, '[{"text": "Ja", "correct": true, "because": "Fördern effektive Ausbildung"}, {"text": "Nein", "correct": false, "because": "Anpassung ist essenziell"}]'),
('00000000-0000-0000-0000-000000000000', 'Können IT-Bereich Services ohne technische Unterstützung effizient betrieben werden?', 2, '[{"text": "Nein", "correct": true, "because": "Support ist für Betrieb nötig"}, {"text": "Ja", "correct": false, "because": "Technische Unterstützung erforderlich"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind IT-Bereich Services im Ausbildungsbetrieb ausschließlich auf Hardware beschränkt?', 2, '[{"text": "Nein", "correct": true, "because": "Umfassen auch Software und Dienstleistungen"}, {"text": "Ja", "correct": false, "because": "Breiteres Spektrum"}]'),
('00000000-0000-0000-0000-000000000000', 'Können IT-Bereich Services die Kundenzufriedenheit im Ausbildungsbetrieb beeinflussen?', 2, '[{"text": "Ja", "correct": true, "because": "Qualität der Services wirkt auf Zufriedenheit"}, {"text": "Nein", "correct": false, "because": "Einfluss ist gegeben"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind IT-Bereich Services nur für große Ausbildungsbetriebe relevant?', 2, '[{"text": "Nein", "correct": true, "because": "Auch kleine Betriebe nutzen sie"}, {"text": "Ja", "correct": false, "because": "Universell anwendbar"}]'),
-- Single-Choice-Fragen (5 Stück)
('00000000-0000-0000-0000-000000000000', 'Welcher IT-Service ist für Auszubildende im Betrieb am wichtigsten?', 3, '[{"text": "Technischer Support", "correct": true, "because": "Hilft bei Problemlösung"}, {"text": "Farbauswahl", "correct": false, "because": "Ästhetisch"}, {"text": "Lieferzeitoptimierung", "correct": false, "because": "Logistisch"}]'),
('00000000-0000-0000-0000-000000000000', 'Welches Ziel verfolgen IT-Bereich Services im Ausbildungsbetrieb?', 2, '[{"text": "Effiziente Arbeitsprozesse", "correct": true, "because": "Fördern Produktivität"}, {"text": "Kostensenkung", "correct": false, "because": "Sekundär"}, {"text": "Markenwerbung", "correct": false, "because": "Marketing"}]'),
('00000000-0000-0000-0000-000000000000', 'Welcher Service gehört typischerweise zum IT-Bereich?', 2, '[{"text": "Netzwerkadministration", "correct": true, "because": "Sichert Konnektivität"}, {"text": "Produktgestaltung", "correct": false, "because": "Design"}, {"text": "Transportplanung", "correct": false, "because": "Logistik"}]'),
('00000000-0000-0000-0000-000000000000', 'Welcher Faktor beeinflusst die Qualität der IT-Bereich Services?', 3, '[{"text": "Kompetenz des Personals", "correct": true, "because": "Wissen ist entscheidend"}, {"text": "Produktgröße", "correct": false, "because": "Physisch"}, {"text": "Lieferantenauswahl", "correct": false, "because": "Sekundär"}]'),
('00000000-0000-0000-0000-000000000000', 'Was ist ein Hauptvorteil von IT-Bereich Services im Ausbildungsbetrieb?', 2, '[{"text": "Unterstützung der Auszubildenden", "correct": true, "because": "Fördert Lernen"}, {"text": "Minimale Kosten", "correct": false, "because": "Nicht primär"}, {"text": "Schnelle Lieferung", "correct": false, "because": "Logistisch"}]'),
-- Multiple-Choice-Fragen (5 Stück)
('00000000-0000-0000-0000-000000000000', 'Welche IT-Bereich Services sind im Ausbildungsbetrieb typisch?', 4, '[{"text": "Technischer Support", "correct": true, "because": "Hilft bei Problemen"}, {"text": "Netzwerkadministration", "correct": true, "because": "Sichert Konnektivität"}, {"text": "Softwarewartung", "correct": true, "because": "Hält Systeme aktuell"}, {"text": "Produktwerbung", "correct": false, "because": "Marketing"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Faktoren beeinflussen die Effektivität von IT-Bereich Services?', 3, '[{"text": "Personalqualifikation", "correct": true, "because": "Wissen ist entscheidend"}, {"text": "Verfügbarkeit", "correct": true, "because": "Sichert Zugriff"}, {"text": "Technische Ausstattung", "correct": true, "because": "Grundlage für Services"}, {"text": "Produktfarbe", "correct": false, "because": "Ästhetisch"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Vorteile bieten IT-Bereich Services im Ausbildungsbetrieb?', 3, '[{"text": "Effiziente Arbeitsprozesse", "correct": true, "because": "Fördert Produktivität"}, {"text": "Kundenzufriedenheit", "correct": true, "because": "Erfüllt Erwartungen"}, {"text": "Lernunterstützung", "correct": true, "because": "Hilft Auszubildenden"}, {"text": "Geringere Anschaffungskosten", "correct": false, "because": "Nicht primär"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Probleme können bei mangelhaften IT-Bereich Services auftreten?', 4, '[{"text": "Arbeitsunterbrechungen", "correct": true, "because": "Fehlender Support"}, {"text": "Unzufriedenheit", "correct": true, "because": "Erwartungen nicht erfüllt"}, {"text": "Lernschwierigkeiten", "correct": true, "because": "Beeinträchtigt Ausbildung"}, {"text": "Schnelle Lieferung", "correct": false, "because": "Logistisch"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Elemente sind für effektive IT-Bereich Services wichtig?', 3, '[{"text": "Kompetentes Personal", "correct": true, "because": "Sichert Qualität"}, {"text": "Zuverlässige Technik", "correct": true, "because": "Grundlage für Betrieb"}, {"text": "Kundenorientierung", "correct": true, "because": "Erfüllt Bedürfnisse"}, {"text": "Produktgestaltung", "correct": false, "because": "Design"}]'),
-- Richtig/Falsch-Kombinationsfragen (5 Stück)
('00000000-0000-0000-0000-000000000000', 'Sind folgende Aussagen richtig? a) IT-Bereich Services unterstützen Auszubildende. b) Technischer Support ist für Services unwichtig.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "Unterstützung ja, Support wichtig"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist richtig"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind diese Aussagen korrekt? a) Netzwerkadministration ist ein IT-Service. b) Services sind nur auf Hardware beschränkt.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "Administration ja, Services umfassender"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist richtig"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind diese Aussagen richtig? a) Kundenzufriedenheit wird durch IT-Services beeinflusst. b) Services sind nur für große Betriebe relevant.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "Zufriedenheit ja, für alle Größen"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist richtig"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind folgende Aussagen korrekt? a) Kompetentes Personal steigert die Servicequalität. b) IT-Services können ohne Technik effizient sein.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "Personal ja, Technik nötig"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist richtig"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind diese Aussagen richtig? a) Softwarewartung ist ein IT-Service. b) Mangelhafte Services führen zu Arbeitsunterbrechungen.', 3, '[{"text": "Beides stimmt", "correct": true, "because": "Wartung und Unterbrechungen korrekt"}, {"text": "Nur a) stimmt", "correct": false, "because": "b) ist auch richtig"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist auch richtig"}, {"text": "Beides falsch", "correct": false, "because": "Beides richtig"}]');

